const {electron}=require('./test-app.cjs'),close=require('./close-test-app.cjs'),fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),{DatabaseSync,backup}=require('node:sqlite');
const root=path.resolve('evidence/category-cleanup-20261023/run-'+Date.now()),profile=path.join(process.env.APPDATA,'YimuCraft'),name='526种AE内置插件效果可视化预设';fs.mkdirSync(root,{recursive:true});
const report={root,name};const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
(async()=>{let app;try{const config=JSON.parse(fs.readFileSync(path.join(profile,'library-config.json'),'utf8'));const db=new DatabaseSync(path.join(config.library,'library.sqlite'),{readOnly:true});const target=db.prepare('SELECT * FROM collections WHERE name=? AND parent IS NULL').all(name);assert.equal(target.length,1);report.target=target[0];report.beforeCategories=db.prepare('WITH RECURSIVE t AS (SELECT * FROM collections WHERE id=? UNION ALL SELECT c.* FROM collections c JOIN t ON c.parent=t.id) SELECT * FROM t').all(target[0].id);await backup(db,path.join(root,'index-before.sqlite'));const digest=()=>crypto.createHash('sha256').update(JSON.stringify(db.prepare('SELECT * FROM assets ORDER BY id').all())).digest('hex');report.beforeAssets=digest();report.sourceBefore=hash('D:/00-aetodo.library/data/aetodo.db');db.close();
const env={...process.env};delete env.YIMU_DATA_DIR;delete env.ELECTRON_RUN_AS_NODE;const launch=()=>electron.launch({executablePath:path.join(process.env.LOCALAPPDATA,'Programs/YimuCraft/YimuCraft.exe'),args:[],env});app=await launch();let page=await app.firstWindow();await page.waitForFunction(()=>document.querySelector('#status')?.textContent.startsWith('就绪'));
report.result=await page.evaluate(id=>window.yimu.command('deleteCollection',id),target[0].id);await page.evaluate(async()=>{state.collection=null;await stats();await refresh();});await close(app);app=await launch();page=await app.firstWindow();await page.waitForFunction(()=>document.querySelector('#status')?.textContent.startsWith('就绪'));
report.after=await page.evaluate(()=>window.yimu.command('stats'));assert.ok(!report.after.collections.some(c=>report.beforeCategories.some(b=>b.id===c.id)));assert.ok(report.after.folders.some(f=>f.folder.includes(name)));assert.equal(report.after.total,65586);assert.ok(!(await page.locator('#collections').innerText()).includes(name));assert.ok((await page.locator('#folders').innerText()).includes('526种'));
await page.evaluate(async()=>{state.duplicateIds=(await window.yimu.command('query',{ext:'ffx',limit:5})).items.map(a=>a.id);await refresh();});await page.screenshot({path:path.join(root,'after.png')});
const check=new DatabaseSync(path.join(config.library,'library.sqlite'),{readOnly:true});report.afterAssets=crypto.createHash('sha256').update(JSON.stringify(check.prepare('SELECT * FROM assets ORDER BY id').all())).digest('hex');check.close();assert.equal(report.afterAssets,report.beforeAssets);report.sourceAfter=hash('D:/00-aetodo.library/data/aetodo.db');assert.equal(report.sourceAfter,report.sourceBefore);report.passed=true;
}catch(e){report.error=e.stack;report.passed=false;process.exitCode=1;}finally{await close(app);fs.writeFileSync(path.join(root,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({root,passed:report.passed,error:report.error,removed:report.beforeCategories?.length,total:report.after?.total}));}})();
